import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export function createStore(filePath) {
  // Writes are chained so two overlapping requests can't clobber each other's save.
  let pending = Promise.resolve();

  async function load() {
    try {
      const raw = await readFile(filePath, 'utf8');
      return JSON.parse(raw);
    } catch (err) {
      if (err.code === 'ENOENT') return [];
      throw err;
    }
  }

  async function save(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.tmp`;
    await writeFile(tmp, JSON.stringify(books, null, 2) + '\n');
    await rename(tmp, filePath);
  }

  function mutate(fn) {
    const run = pending.then(async () => {
      const books = await load();
      const result = fn(books);
      await save(books);
      return result;
    });
    pending = run.catch(() => {});
    return run;
  }

  return {
    async list() {
      return load();
    },

    async get(id) {
      const books = await load();
      return books.find((b) => b.id === id) ?? null;
    },

    add({ title, author, notes = '' }) {
      title = title.trim();
      author = author.trim();
      if (!title) throw new ValidationError('Title is required.');
      if (!author) throw new ValidationError('Author is required.');
      return mutate((books) => {
        const book = {
          id: randomUUID(),
          title,
          author,
          notes: notes.trim(),
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        return book;
      });
    },

    finish(id) {
      return mutate((books) => {
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        if (!book.finishedAt) book.finishedAt = new Date().toISOString();
        return book;
      });
    },

    updateNotes(id, notes) {
      return mutate((books) => {
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        book.notes = notes.trim();
        return book;
      });
    },
  };
}

export class ValidationError extends Error {}

