export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

const css = `
  :root { color-scheme: light dark; }
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; }
  h1, h2 { line-height: 1.2; }
  h2 { margin-top: 2rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: .5rem 0; border-bottom: 1px solid #8884; }
  ul.books a { font-weight: 600; text-decoration: none; }
  ul.books a:hover { text-decoration: underline; }
  .author, .meta { opacity: .7; }
  .empty { opacity: .7; font-style: italic; }
  form label { display: block; margin-top: .75rem; }
  form input, form textarea { display: block; width: 100%; box-sizing: border-box; font: inherit; padding: .4rem; margin-top: .25rem; }
  form textarea { min-height: 6rem; }
  button { font: inherit; padding: .45rem .9rem; margin-top: .75rem; cursor: pointer; }
  .error { color: #c0392b; }
  .notes { white-space: pre-wrap; }
  .share { font-size: .9rem; word-break: break-all; }
  nav a { text-decoration: none; }
`;

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${css}</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  return `<ul class="books">${books
    .map(
      (b) => `<li><a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a> <span class="author">by ${escapeHtml(b.author)}</span></li>`,
    )
    .join('')}</ul>`;
}

export function homePage(books, { error = '', values = {} } = {}) {
  const reading = books.filter((b) => !b.finishedAt).sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books.filter((b) => b.finishedAt).sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return page(
    'My Books',
    `<h1>My Books</h1>

<h2>Currently reading</h2>
${bookList(reading, "You're not reading anything right now.")}

<h2>Finished</h2>
${bookList(finished, 'Nothing finished yet.')}

<h2 id="add">Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
<form method="post" action="/books">
  <label>Title <input name="title" required value="${escapeHtml(values.title)}"></label>
  <label>Author <input name="author" required value="${escapeHtml(values.author)}"></label>
  <label>Notes <textarea name="notes">${escapeHtml(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, shareUrl) {
  const status = book.finishedAt
    ? `Finished ${formatDate(book.finishedAt)}`
    : `Currently reading · added ${formatDate(book.addedAt)}`;

  return page(
    `${book.title} – My Books`,
    `<nav><a href="/">&larr; All books</a></nav>
<h1>${escapeHtml(book.title)}</h1>
<p class="author">by ${escapeHtml(book.author)}</p>
<p class="meta">${escapeHtml(status)}</p>
${
  book.finishedAt
    ? ''
    : `<form method="post" action="/books/${escapeHtml(book.id)}/finish"><button type="submit">Mark as finished</button></form>`
}

<h2>Notes</h2>
${book.notes ? `<p class="notes">${escapeHtml(book.notes)}</p>` : '<p class="empty">No notes yet.</p>'}
<form method="post" action="/books/${escapeHtml(book.id)}/notes">
  <label>Edit notes <textarea name="notes">${escapeHtml(book.notes)}</textarea></label>
  <button type="submit">Save notes</button>
</form>

<h2>Share</h2>
<p class="share">Link to this book: <a href="${escapeHtml(shareUrl)}">${escapeHtml(shareUrl)}</a></p>`,
  );
}

export function notFoundPage() {
  return page(
    'Not found – My Books',
    `<nav><a href="/">&larr; All books</a></nav>
<h1>Book not found</h1>
<p>There's no book at this address. It may have been removed.</p>`,
  );
}

