import { createServer } from 'node:http';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { createStore, ValidationError } from './lib/store.js';
import { bookPage, homePage, notFoundPage } from './lib/views.js';

const here = dirname(fileURLToPath(import.meta.url));

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
    const path = url.pathname.replace(/\/+$/, '') || '/';

    if (req.method === 'GET' && path === '/') {
      return html(res, 200, homePage(await store.list()));
    }

    if (req.method === 'POST' && path === '/books') {
      const form = await readForm(req);
      try {
        const book = await store.add({
          title: form.get('title') ?? '',
          author: form.get('author') ?? '',
          notes: form.get('notes') ?? '',
        });
        return redirect(res, `/books/${book.id}`);
      } catch (err) {
        if (!(err instanceof ValidationError)) throw err;
