    expect(detail).toContain('Great &lt;b&gt;book&lt;/b&gt;');
    expect(detail).not.toContain('<b>book</b>');
  });

  it('re-renders the form with an error when the title is missing', async () => {
    const res = await post('/books', { title: '', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const body = await res.text();
    expect(body).toContain('Title is required.');
    expect(body).toContain('value="Someone"');
    expect(body).toContain('>kept</textarea>');
  });

  it('returns 404 for unknown books and paths', async () => {
    expect((await fetch(base + '/books/does-not-exist')).status).toBe(404);
    expect((await fetch(base + '/nope')).status).toBe(404);
    expect((await post('/books/does-not-exist/finish', {})).status).toBe(404);
  });
});
